import { useState } from "react"
import { CalendarIcon, TagIcon } from "lucide-react"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { useCollection } from "@/lib/mini/store"
import { DateField, ExpandList, TextField, type ExpandItem } from "./index"

type Task = ExpandItem & { due?: string; tags?: string }

function daysFromToday(offset: number): string {
  const date = new Date()
  date.setDate(date.getDate() + offset)
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

const seed: Task[] = [
  { id: "t1", title: "Buy oat milk" },
  { id: "t2", title: "Return library books", due: daysFromToday(1) },
  { id: "t3", title: "Pick up dry cleaning", tags: "errand" },
  {
    id: "t4",
    title: "Renew passport",
    due: daysFromToday(14),
    notes:
      "Bring two photos and the old passport. Appointment needs booking online first.",
  },
  { id: "t5", title: "Book dentist", due: daysFromToday(6) },
  { id: "t6", title: "Mail parcel to Sam", tags: "post, errand" },
  {
    id: "t7",
    title:
      "Compare quotes for replacing the back-door lock, the garden gate latch and the side-window handles before the landlord's inspection",
  },
  { id: "t8", title: "Water the plants" },
]

const fields = [
  DateField<Task>("due", "Due date", <CalendarIcon />),
  TextField<Task>("tags", "Tags", <TagIcon />),
]

const previews = ["live", "empty", "loading", "error"] as const
type Preview = (typeof previews)[number]

function StatePreview({
  preview,
  onExit,
}: {
  preview: Exclude<Preview, "live">
  onExit(): void
}) {
  if (preview === "loading") return <LoadingState label="Loading items" />
  if (preview === "error") {
    return (
      <ErrorState
        error={new Error("Could not read the saved items")}
        onRetry={onExit}
      />
    )
  }
  return (
    <EmptyState
      title="Nothing here yet"
      description="Press N to add an item"
      action={
        <Button size="sm" onClick={onExit}>
          Back to live list
        </Button>
      }
    />
  )
}

export default function Demo() {
  const [preview, setPreview] = useState<Preview>("live")
  const { replaceAll } = useCollection<Task>("expand-in-place-demo", seed)

  const toolbar = (
    <div
      role="group"
      aria-label="State preview (demo only)"
      className="flex items-center gap-1"
    >
      <span className="text-xs text-muted-foreground">Preview state</span>
      {previews.map((name) => (
        <Button
          key={name}
          size="xs"
          variant={preview === name ? "secondary" : "ghost"}
          aria-pressed={preview === name}
          onClick={() => setPreview(name)}
        >
          {name}
        </Button>
      ))}
      <Button size="xs" variant="outline" onClick={() => void replaceAll(seed)}>
        Reset sample data
      </Button>
    </div>
  )

  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="flex h-10 shrink-0 items-center gap-3 border-b px-3">
        <h2 data-mini="title" className="text-sm font-semibold tracking-tight">Errands</h2>
        <div className="ml-auto">{toolbar}</div>
      </header>
      <div className="min-h-0 flex-1 overflow-auto">
        {preview === "live" ? (
          <ExpandList<Task>
            collection="expand-in-place-demo"
            seed={seed}
            fields={fields}
            newItem={() => ({ id: crypto.randomUUID(), title: "" })}
            emptyTitle="No errands yet"
          />
        ) : (
          <StatePreview preview={preview} onExit={() => setPreview("live")} />
        )}
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { XIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Textarea } from "@/components/ui/textarea"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import type { ExpandField, ExpandItem } from "./types"

const bareTextarea =
  "min-h-0 resize-none rounded-none border-0 bg-transparent p-0 text-sm shadow-none focus-visible:ring-0 dark:bg-transparent"

/**
 * The open editing card for one item: title, notes, a row per filled field and
 * an icon strip for the empty ones. Edits are reported through `onChange` as
 * they are typed. Esc and Cmd/Ctrl+Enter call `onClose`, including while
 * typing in the card; Esc leaves an open field popover to close first.
 */
export function ExpandCard<T extends ExpandItem>({
  item,
  fields,
  onChange,
  onClose,
}: {
  item: T
  fields: ExpandField<T>[]
  onChange(patch: Partial<T>): void
  onClose(): void
}) {
  // typing is mirrored locally because the store round-trips asynchronously and would drop keystrokes
  const [title, setTitle] = useState(item.title)
  const [notes, setNotes] = useState(item.notes ?? "")
  const [activeKey, setActiveKey] = useState<string | null>(null)
  const [entered, setEntered] = useState(false)
  const [settled, setSettled] = useState(false)
  const titleRef = useRef<HTMLTextAreaElement>(null)
  const notesRef = useRef<HTMLTextAreaElement>(null)
  const cardRef = useRef<HTMLDivElement>(null)
  const activeKeyRef = useRef<string | null>(null)
  // the field's icon turns into a row once it is filled, so the popover re-reads its anchor on every frame
  const anchorRef = useRef({
    getBoundingClientRect: () => {
      const card = cardRef.current
      const key = activeKeyRef.current
      const target =
        card?.querySelector(`[data-field-anchor="${CSS.escape(key ?? "")}"]`) ?? card
      return (target ?? document.body).getBoundingClientRect()
    },
  })

  const collapseKeys = { enableOnFormTags: true, enableOnContentEditable: true } as const
  useHotkeys("escape", (event) => {
    if (!event.defaultPrevented) onClose()
  }, collapseKeys)
  useHotkeys("mod+enter", onClose, { ...collapseKeys, preventDefault: true })

  useEffect(() => {
    const field = titleRef.current
    if (field) {
      field.focus()
      field.setSelectionRange(field.value.length, field.value.length)
    }
    const frame = requestAnimationFrame(() => setEntered(true))
    const timer = window.setTimeout(() => {
      setSettled(true)
      cardRef.current?.scrollIntoView({ block: "nearest" })
    }, 170)
    return () => {
      cancelAnimationFrame(frame)
      window.clearTimeout(timer)
    }
  }, [])

  function openEditor(key: string) {
    const next = activeKeyRef.current === key ? null : key
    activeKeyRef.current = next
    setActiveKey(next)
  }

  function closeEditor() {
    activeKeyRef.current = null
    setActiveKey(null)
  }

  const filled = fields.filter((field) => field.isSet(item))
  const empty = fields.filter((field) => !field.isSet(item))
  const activeField = fields.find((field) => field.key === activeKey)

  return (
    <div
      className={cn(
        "grid transition-[grid-template-rows] duration-150 ease-out motion-reduce:transition-none",
        entered ? "grid-rows-[1fr]" : "grid-rows-[0fr]"
      )}
    >
      <div className={cn("min-h-0", !settled && "overflow-hidden")}>
        <div
          ref={cardRef}
          role="group"
          data-mini="surface"
          aria-label={`Edit ${item.title || "new item"}`}
          className="-mx-3.5 my-1.5 flex flex-col gap-2 rounded-xl bg-card p-3 text-card-foreground shadow-md"
        >
          <ScrollArea className="[&_[data-radix-scroll-area-viewport]]:max-h-[70svh] [&_[data-radix-scroll-area-viewport]>div]:block!">
            <div className="flex flex-col gap-1.5">
              <div className="flex items-start gap-2.5">
                <Checkbox
                  className="mt-0.5"
                  aria-label="Done"
                  checked={item.done === true}
                  onCheckedChange={(checked) =>
                    onChange({ done: checked === true } as Partial<T>)
                  }
                />
                <Textarea
                  ref={titleRef}
                  aria-label="Title"
                  placeholder="New item"
                  rows={1}
                  value={title}
                  className={cn(bareTextarea, "font-medium")}
                  onChange={(event) => {
                    setTitle(event.target.value)
                    onChange({ title: event.target.value } as Partial<T>)
                  }}
                  onKeyDown={(event) => {
                    if (event.key !== "Enter" || event.shiftKey || event.metaKey || event.ctrlKey) return
                    if (event.nativeEvent.isComposing) return
                    event.preventDefault()
                    notesRef.current?.focus()
                  }}
                />
              </div>
              <Textarea
                ref={notesRef}
                aria-label="Notes"
                placeholder="Notes"
                rows={1}
                value={notes}
                className={cn(bareTextarea, "ml-[26px] w-[calc(100%-26px)] text-muted-foreground")}
                onChange={(event) => {
                  setNotes(event.target.value)
                  onChange({ notes: event.target.value } as Partial<T>)
                }}
              />
              {filled.map((field) => (
                <div
                  key={field.key}
                  data-field-anchor={field.key}
                  className="group/field ml-[26px] flex items-center gap-1 rounded-md hover:bg-muted/60"
                >
                  <button
                    type="button"
                    aria-haspopup="dialog"
                    aria-expanded={activeKey === field.key}
                    onClick={() => openEditor(field.key)}
                    className="flex min-w-0 flex-1 items-center gap-2 rounded-md px-1 py-0.5 text-left text-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
                  >
                    <span aria-hidden className="text-muted-foreground [&_svg]:size-3.5">
                      {field.icon}
                    </span>
                    <span className="text-muted-foreground">{field.label}:</span>
                    <Badge variant="secondary" className="max-w-full truncate">
                      {field.display(item)}
                    </Badge>
                  </button>
                  <Button
                    variant="ghost"
                    size="icon-xs"
                    aria-label={`Clear ${field.label}`}
                    className="opacity-0 group-hover/field:opacity-100 focus-visible:opacity-100"
                    onClick={() => {
                      onChange(field.clear(item))
                      if (activeKey === field.key) closeEditor()
                      titleRef.current?.focus()
                    }}
                  >
                    <XIcon />
                  </Button>
                </div>
              ))}
            </div>
          </ScrollArea>
          {empty.length > 0 ? (
            <div className="flex justify-end gap-0.5">
              {empty.map((field) => (
                <Tooltip key={field.key}>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon-sm"
                      data-field-anchor={field.key}
                      aria-label={`Add ${field.label}`}
                      aria-haspopup="dialog"
                      aria-expanded={activeKey === field.key}
                      onClick={() => openEditor(field.key)}
                    >
                      {field.icon}
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>{field.label}</TooltipContent>
                </Tooltip>
              ))}
            </div>
          ) : null}
        </div>
      </div>
      <Popover open={activeField !== undefined} onOpenChange={(open) => !open && closeEditor()}>
        <PopoverAnchor virtualRef={anchorRef} />
        <PopoverContent
          align="start"
          aria-label={activeField?.label}
          className="w-auto"
          updatePositionStrategy="always"
          onCloseAutoFocus={(event) => {
            event.preventDefault()
            if (titleRef.current?.isConnected) titleRef.current.focus()
          }}
          onInteractOutside={(event) => {
            // lets the field's own button toggle the editor instead of closing and instantly reopening it
            if ((event.target as Element).closest("[data-field-anchor]")) event.preventDefault()
          }}
        >
          {activeField ? (
            <activeField.Editor
              key={activeField.key}
              item={item}
              onChange={onChange}
              onClose={closeEditor}
            />
          ) : null}
        </PopoverContent>
      </Popover>
    </div>
  )
}

import { useEffect, useRef, useState, type ReactNode } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { AlignLeftIcon, PlusIcon } from "lucide-react"
import { toast } from "sonner"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Kbd } from "@/components/ui/kbd"
import { useCollection } from "@/lib/mini/store"
import { cn } from "@/lib/utils"
import { ExpandCard } from "./expand-card"
import type { ExpandField, ExpandItem } from "./types"

function toError(cause: unknown): Error {
  return cause instanceof Error ? cause : new Error(String(cause))
}

function defaultOnError(error: Error) {
  toast.error("Could not save changes", { description: error.message })
}

function ExpandRow<T extends ExpandItem>({
  item,
  fields,
  selected,
  tabbable,
  renderRow,
  registerButton,
  onSelect,
  onOpen,
  onToggleDone,
}: {
  item: T
  fields: ExpandField<T>[]
  selected: boolean
  tabbable: boolean
  renderRow?: (item: T) => ReactNode
  registerButton(element: HTMLButtonElement | null): void
  onSelect(): void
  onOpen(): void
  onToggleDone(done: boolean): void
}) {
  const setFields = fields.filter((field) => field.isSet(item))
  const name = item.title || "Untitled"
  return (
    <li
      data-item-id={item.id}
      data-mini="row"
      data-active={selected ? "" : undefined}
      className={cn(
        "flex items-center gap-2.5 rounded-md px-3 py-1 hover:bg-muted/60",
        selected && "bg-muted"
      )}
    >
      <Checkbox
        aria-label={`Mark "${name}" done`}
        checked={item.done === true}
        onCheckedChange={(checked) => onToggleDone(checked === true)}
      />
      <button
        ref={registerButton}
        type="button"
        data-expand-row
        tabIndex={tabbable ? 0 : -1}
        aria-current={selected ? "true" : undefined}
        aria-expanded={false}
        onFocus={onSelect}
        onClick={onOpen}
        className="flex min-w-0 flex-1 items-center gap-2 rounded-sm text-left text-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
      >
        <span
          className={cn(
            "min-w-0 flex-1 truncate",
            item.done && "text-muted-foreground line-through",
            !item.title && "text-muted-foreground italic"
          )}
        >
          {renderRow ? renderRow(item) : name}
        </span>
        {item.notes || setFields.length > 0 ? (
          <span className="flex shrink-0 items-center gap-1.5 text-muted-foreground [&_svg]:size-3.5">
            {item.notes ? <AlignLeftIcon aria-hidden /> : null}
            {setFields.map((field) => (
              <span key={field.key} aria-hidden>
                {field.glyph}
              </span>
            ))}
            <span className="sr-only">
              {[item.notes ? "Has notes" : null, ...setFields.map((field) => field.label)]
                .filter(Boolean)
                .join(", ")}
            </span>
          </span>
        ) : null}
      </button>
    </li>
  )
}

/**
 * Single-column list whose rows open in place into an `ExpandCard`, one at a
 * time. Owns row selection, which card is open and the list hotkeys, and saves
 * every edit through the base collection store as it is typed.
 */
export function ExpandList<T extends ExpandItem>({
  collection,
  seed,
  fields,
  newItem,
  renderRow,
  emptyTitle = "Nothing here yet",
  onError = defaultOnError,
}: {
  collection: string
  seed?: T[]
  fields: ExpandField<T>[]
  newItem(): T
  renderRow?: (item: T) => ReactNode
  emptyTitle?: string
  onError?: (error: Error) => void
}) {
  const { items, status, error, add, update, remove } = useCollection<T>(collection, seed)
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [openId, setOpenId] = useState<string | null>(null)
  const [freshId, setFreshId] = useState<string | null>(null)
  const [failedSaves, setFailedSaves] = useState(0)
  const rowButtons = useRef(new Map<string, HTMLButtonElement>())
  const refocusId = useRef<string | null>(null)
  // the store publishes an edit only after its write lands, so props lag what the user already typed
  const typedTitles = useRef(new Map<string, string>())

  const ready = status === "ready"
  const selected = items.some((item) => item.id === selectedId) ? selectedId : null
  const openItem = items.find((item) => item.id === openId)

  function guard(write: Promise<void>) {
    write.catch((cause: unknown) => {
      onError(toError(cause))
      setFailedSaves((count) => count + 1)
    })
  }

  /** Closes the open card, dropping a never-titled new item, and returns the row that should take focus. */
  function closeOpenCard(): string | null {
    if (openId === null) return null
    const closing = items.find((item) => item.id === openId)
    const title = typedTitles.current.get(openId) ?? closing?.title ?? ""
    typedTitles.current.delete(openId)
    setOpenId(null)
    if (openId !== freshId) return openId
    setFreshId(null)
    if (title.trim() !== "") return openId
    // the remove queues behind any title write still in flight, so it lands last
    guard(remove(openId))
    if (!closing) return items[items.length - 1]?.id ?? null
    const index = items.indexOf(closing)
    return (items[index - 1] ?? items[index + 1])?.id ?? null
  }

  function saveEdit(id: string, patch: Partial<T>) {
    if (typeof patch.title === "string") typedTitles.current.set(id, patch.title)
    guard(update(id, patch))
  }

  function collapse() {
    const focusId = closeOpenCard()
    refocusId.current = focusId
    setSelectedId(focusId)
  }

  function openRow(id: string) {
    if (id === openId) return
    closeOpenCard()
    refocusId.current = null
    setSelectedId(id)
    setOpenId(id)
  }

  function addItem() {
    if (!ready) return
    const created = newItem()
    closeOpenCard()
    refocusId.current = null
    typedTitles.current.set(created.id, created.title)
    setFreshId(created.id)
    setSelectedId(created.id)
    setOpenId(created.id)
    add(created).catch((cause: unknown) => {
      onError(toError(cause))
      typedTitles.current.delete(created.id)
      setOpenId(null)
      setFreshId(null)
    })
  }

  function moveSelection(step: 1 | -1) {
    if (items.length === 0) return
    const index = selected === null ? -1 : items.findIndex((item) => item.id === selected)
    const target =
      index === -1
        ? items[step === 1 ? 0 : items.length - 1]
        : items[Math.min(items.length - 1, Math.max(0, index + step))]
    setSelectedId(target.id)
    rowButtons.current.get(target.id)?.focus()
  }

  const latest = useRef({ collapse, openRow, addItem, moveSelection })
  useEffect(() => {
    latest.current = { collapse, openRow, addItem, moveSelection }
  })

  useEffect(() => {
    if (openId !== null || refocusId.current === null) return
    const button = rowButtons.current.get(refocusId.current)
    if (!button) return
    button.focus()
    refocusId.current = null
  }, [openId, items])

  const browsing = ready && openId === null
  useHotkeys("down", () => latest.current.moveSelection(1), { enabled: browsing, preventDefault: true })
  useHotkeys("up", () => latest.current.moveSelection(-1), { enabled: browsing, preventDefault: true })
  useHotkeys(
    "enter",
    (event) => {
      // a focused row button opens itself through its click
      if ((event.target as Element).closest("button, a, [role=checkbox]")) return
      if (selected !== null) latest.current.openRow(selected)
    },
    { enabled: browsing && selected !== null }
  )
  useHotkeys(
    "n",
    (event) => {
      if ((event.target as Element).closest("[role=dialog]")) return
      latest.current.addItem()
    },
    { enabled: ready, preventDefault: true }
  )

  let body: ReactNode
  if (status === "loading") {
    body = <LoadingState label="Loading items" />
  } else if (status === "error") {
    body = (
      <ErrorState
        error={error ?? new Error("Could not load items")}
        onRetry={() => window.location.reload()}
      />
    )
  } else if (items.length === 0 && openId === null) {
    body = (
      <EmptyState
        title={emptyTitle}
        description="Press N to add an item"
        action={
          <Button size="sm" onClick={addItem}>
            <PlusIcon /> Add item
          </Button>
        }
      />
    )
  } else {
    const firstId = items[0]?.id
    body = (
      <ul aria-label="Items" className="flex flex-col">
        {items.map((item) =>
          item.id === openItem?.id ? (
            <li key={item.id} data-item-id={item.id}>
              <ExpandCard
                key={failedSaves}
                item={item}
                fields={fields}
                onChange={(patch) => saveEdit(item.id, patch)}
                onClose={() => latest.current.collapse()}
              />
            </li>
          ) : (
            <ExpandRow
              key={item.id}
              item={item}
              fields={fields}
              selected={item.id === selected}
              tabbable={selected === null ? item.id === firstId : item.id === selected}
              renderRow={renderRow}
              registerButton={(element) => {
                if (element) rowButtons.current.set(item.id, element)
                else rowButtons.current.delete(item.id)
              }}
              onSelect={() => setSelectedId(item.id)}
              onOpen={() => openRow(item.id)}
              onToggleDone={(done) => guard(update(item.id, { done } as Partial<T>))}
            />
          )
        )}
      </ul>
    )
  }

  return (
    <div className="flex min-h-full flex-col">
      <div className="mx-auto w-full max-w-[820px] flex-1 px-6 py-4">{body}</div>
      <div className="sticky bottom-0 border-t bg-background/90 backdrop-blur">
        <div className="mx-auto flex w-full max-w-[820px] items-center justify-between px-6 py-2">
          {openId === null ? (
            <Button variant="ghost" size="sm" disabled={!ready} onClick={addItem}>
              <PlusIcon /> New item <Kbd>N</Kbd>
            </Button>
          ) : (
            <Button variant="ghost" size="sm" onClick={collapse}>
              Done <Kbd>⌘↵</Kbd>
            </Button>
          )}
        </div>
      </div>
    </div>
  )
}

import { useState, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Input } from "@/components/ui/input"
import type { ExpandField, ExpandItem } from "./types"

function readValue(item: ExpandItem, key: string): unknown {
  return (item as Record<string, unknown>)[key]
}

function patchOf<T extends ExpandItem>(key: string, value: string | undefined): Partial<T> {
  return { [key]: value } as unknown as Partial<T>
}

function hasText(value: unknown): value is string {
  return typeof value === "string" && value !== ""
}

function parseDay(value: string): Date {
  const [year, month, day] = value.split("-").map(Number)
  return new Date(year, month - 1, day)
}

function formatDay(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

function ClearButton({ label, onClick }: { label: string; onClick(): void }) {
  return (
    <Button variant="ghost" size="sm" onClick={onClick}>
      Clear {label.toLowerCase()}
    </Button>
  )
}

function DateEditor<T extends ExpandItem>({
  field,
  item,
  onChange,
  onClose,
}: {
  field: Pick<ExpandField<T>, "key" | "label">
  item: T
  onChange(patch: Partial<T>): void
  onClose(): void
}) {
  const current = readValue(item, field.key)
  return (
    <div className="flex flex-col items-stretch">
      <Calendar
        mode="single"
        selected={hasText(current) ? parseDay(current) : undefined}
        defaultMonth={hasText(current) ? parseDay(current) : undefined}
        onSelect={(date) => {
          if (!date) return
          onChange(patchOf<T>(field.key, formatDay(date)))
          onClose()
        }}
      />
      {hasText(current) ? (
        <ClearButton
          label={field.label}
          onClick={() => {
            onChange(patchOf<T>(field.key, undefined))
            onClose()
          }}
        />
      ) : null}
    </div>
  )
}

function TextEditor<T extends ExpandItem>({
  field,
  item,
  onChange,
  onClose,
}: {
  field: Pick<ExpandField<T>, "key" | "label">
  item: T
  onChange(patch: Partial<T>): void
  onClose(): void
}) {
  const stored = readValue(item, field.key)
  const [draft, setDraft] = useState(hasText(stored) ? stored : "")
  return (
    <div className="flex w-64 flex-col gap-2">
      <Input
        aria-label={field.label}
        value={draft}
        placeholder={field.label}
        onChange={(event) => {
          setDraft(event.target.value)
          onChange(patchOf<T>(field.key, event.target.value))
        }}
        onKeyDown={(event) => {
          if (event.key === "Enter") onClose()
        }}
      />
      {draft !== "" ? (
        <ClearButton
          label={field.label}
          onClick={() => {
            onChange(patchOf<T>(field.key, undefined))
            onClose()
          }}
        />
      ) : null}
    </div>
  )
}

/** Date stored as a `YYYY-MM-DD` string under `key`, edited in a calendar popover. */
export function DateField<T extends ExpandItem>(
  key: keyof T & string,
  label: string,
  icon: ReactNode
): ExpandField<T> {
  return {
    key,
    label,
    icon,
    glyph: icon,
    isSet: (item) => hasText(readValue(item, key)),
    display: (item) => {
      const value = readValue(item, key)
      return hasText(value)
        ? parseDay(value).toLocaleDateString(undefined, {
            weekday: "short",
            day: "numeric",
            month: "short",
          })
        : null
    },
    clear: () => patchOf<T>(key, undefined),
    Editor: (props) => <DateEditor field={{ key, label }} {...props} />,
  }
}

/** Free text stored as a string under `key`, edited in an input popover. */
export function TextField<T extends ExpandItem>(
  key: keyof T & string,
  label: string,
  icon: ReactNode
): ExpandField<T> {
  return {
    key,
    label,
    icon,
    glyph: icon,
    isSet: (item) => hasText(readValue(item, key)),
    display: (item) => {
      const value = readValue(item, key)
      return hasText(value) ? value : null
    },
    clear: () => patchOf<T>(key, undefined),
    Editor: (props) => <TextEditor field={{ key, label }} {...props} />,
  }
}

import type { ReactNode } from "react"

export type ExpandItem = {
  id: string
  title: string
  notes?: string
  done?: boolean
}

/** One optional field of an item: an icon in the strip while empty, a row in the card once set. */
export type ExpandField<T extends ExpandItem> = {
  /** Unique within the list; also the identity used for strip order. */
  key: string
  /** Tooltip, editor label and row label. */
  label: string
  /** Supplied by the app; the block ships no icon set. */
  icon: ReactNode
  /** False means the field shows as a strip icon and has no row. */
  isSet(item: T): boolean
  /** Value shown in the filled row. */
  display(item: T): ReactNode
  /** Patch that empties the field. */
  clear(item: T): Partial<T>
  /** Rendered inside the field's popover; `onChange` saves immediately. */
  Editor(props: {
    item: T
    onChange(patch: Partial<T>): void
    onClose(): void
  }): ReactNode
  /** Trailing glyph on the collapsed row while the field is set. */
  glyph?: ReactNode
}
